import*as Platform from"../../core/platform/platform.js";import*as FormatterWorker from"./formatter_worker.js";self.onmessage=function(e){const r=e.data.method,t=e.data.params;if(r)switch(r){case"format":self.postMessage(FormatterWorker.FormatterWorker.format(t.mimeType,t.content,t.indentString));break;case"parseCSS":FormatterWorker.CSSRuleParser.parseCSS(t.content,self.postMessage);break;case"javaScriptSubstitute":self.postMessage(FormatterWorker.Substitute.substituteExpression(t.content,t.mapping));break;case"javaScriptScopeTree":self.postMessage(FormatterWorker.ScopeParser.parseScopes(t.content,t.sourceType)?.export());break;case"evaluatableJavaScriptSubstring":self.postMessage(FormatterWorker.FormatterWorker.evaluatableJavaScriptSubstring(t.content));break;default:Platform.assertNever(r,`Unsupport method name: ${r}`)}},self.postMessage("workerReady");